                  <div className="photo-box">
                    {selectedCard.application?.photo_path ? (
                      <img
                        src={`http://127.0.0.1:8000/${selectedCard.application.photo_path}`}
                        alt="Applicant"
                        className="card-photo-img"
                      />
                    ) : (
                      <div className="photo-text">Photographs</div>
                    )}
